-- Confrontações dos 16 lotes à venda do Rota dos Ventos, lidas da planta
-- (LOTES Q01-Q05). Áreas conferem com lotes.tamanho_m2. Aguardando conferência do financeiro.
-- Aplicada em produção em 16/11/2026.
on conflict (condominio_slug,quadra,lote_numero) do update set area_privativa=excluded.area_privativa,area_comum=excluded.area_comum,area_real=excluded.area_real,area_texto=excluded.area_texto,confrontacoes=excluded.confrontacoes,fonte=excluded.fonte,atualizado_em=now();
